struct Parser {
  std::unordered_map<std::uint64_t, Memo> memo;   // key = (rule_id << 32) | pos
  std::optional<Node> rule(RuleId r, std::size_t pos) {
    const std::uint64_t key = (static_cast<std::uint64_t>(r) << 32) | pos;
    auto it = memo.find(key);
    if (it != memo.end()) return it->second.node;  // already computed: success or failure
    Memo m{rule_impl(r, pos)};                     // may backtrack speculatively
    memo.emplace(key, m);                          // failures are memoized too
    return m.node;
  }
};

