struct Parser {
  std::vector<std::vector<Memo>> memo;             // memo[rule][pos]
  Parser(std::size_t rules, std::size_t len)
      : memo(rules, std::vector<Memo>(len + 1)) {}
  const Memo &rule(RuleId r, std::size_t pos) {
    Memo &cell = memo[r][pos];                     // arithmetic index, no hash
    if (!cell.done) cell = rule_impl(r, pos);      // failures cached in the same cell
    return cell;
  }
};
